    {"claim": "The machinery-licensing analogy is a category error that collapses under its own logic", "targets": []},
    {"claim": "AI content classification systems exhibit documented systemic bias that would algorithmically harden historical injustice into information access policy", "targets": []},
    {"claim": "The proposal ignores the producers of AI-generated misinformation and punishes the consumers", "targets": []},
    {"claim": "No democratic society has accepted this level of state control over knowledge access for any previous information technology", "targets": []}
  ],
